import React from 'react'
import { Box, useTheme } from '@mui/material'
import type { PreviewType } from './types'

export const FeatureScreenPreview: React.FC<{ previewType: PreviewType }> = ({ previewType }) => {
  const theme = useTheme()
  const style = { width: '100%', height: 'auto', display: 'block', borderRadius: 1, border: `1px solid ${theme.colors.alpha.black[10]}` }

  const renderPreview = () => {
    switch (previewType) {
      case 'member-search':
        return (
          <Box
            component="img"
            src="/static/images/intro/club_search_page.png"
            alt="동아리 검색 페이지"
            sx={style}
          />
        )
      case 'member-recruit':
        return (
          <Box
            component="img"
            src="/static/images/intro/club_recruiting_page.png"
            alt="모집 공고 페이지"
            sx={style}
          />
        )
      case 'member-activity':
        return (
          <Box
            component="img"
            src="/static/images/intro/club_activity_and_review.png"
            alt="활동 기록 및 활동 후기"
            sx={style}
          />
        )
      case 'member-benefit':
        return (
          <Box
            component="img"
            src="/static/images/intro/benefit_coupon.png"
            alt="제휴 혜택"
            sx={style}
          />
        )
      case 'manager-recruit':
        return (
          <Box
            component="img"
            src="/static/images/intro/club_recruiting_manage.png"
            alt="모집 관리 페이지"
            sx={style}
          />
        )
      case 'manager-members':
        return (
          <Box
            component="img"
            src="/static/images/intro/club_members_manage.png"
            alt="동아리 회원 명단"
            sx={style}
          />
        )
      case 'manager-attendance':
        return (
          <Box
            component="img"
            src="/static/images/intro/club_conference_manage.png"
            alt="동아리 행사 관리"
            sx={style}
          />
        )
      case 'manager-settings':
        return (
          <Box
            component="img"
            src="/static/images/intro/club_info_manage.png"
            alt="동아리 기본 정보 설정"
            sx={style}
          />
        )
      case 'manager-post':
        return (
          <Box
            component="img"
            src="/static/images/intro/club_posting_manage.png"
            alt="동아리 활동 포스팅"
            sx={style}
          />
        )
      case 'manager-finance':
        return (
          <Box
            component="img"
            src="/static/images/intro/club_finance_manage.png"
            alt="동아리 회비 관리"
            sx={style}
          />
        )
      default:
        return null
    }
  }

  return (
    renderPreview()
  )
}
